      created_at INTEGER NOT NULL, -- epoch ms (Date.now())
      harness TEXT NOT NULL DEFAULT 'opencode', rebase_status TEXT NOT NULL DEFAULT 'ok',
      UNIQUE(session_id, sequence)
    );

