CREATE TRIGGER compartment_history_au AFTER UPDATE ON compartments BEGIN
            INSERT INTO compartment_history_versions(session_id, version, rewrite_version) VALUES (OLD.session_id, 1, CASE WHEN COALESCE((SELECT enabled FROM context_privilege_state WHERE id=1),0)=0 THEN 1 ELSE 0 END)
            ON CONFLICT(session_id) DO UPDATE SET version = version + 1, rewrite_version = rewrite_version + CASE WHEN COALESCE((SELECT enabled FROM context_privilege_state WHERE id=1),0)=0 THEN 1 ELSE 0 END;
            INSERT INTO compartment_history_versions(session_id, version, rewrite_version)
                SELECT NEW.session_id, 1, CASE WHEN COALESCE((SELECT enabled FROM context_privilege_state WHERE id=1),0)=0 THEN 1 ELSE 0 END WHERE NEW.session_id != OLD.session_id
            ON CONFLICT(session_id) DO UPDATE SET version = version + 1, rewrite_version = rewrite_version + CASE WHEN COALESCE((SELECT enabled FROM context_privilege_state WHERE id=1),0)=0 THEN 1 ELSE 0 END;
        END;

CREATE INDEX idx_plugin_messages_session ON plugin_messages(session_id);

CREATE INDEX idx_user_memory_candidates_session ON user_memory_candidates(session_id);

CREATE TABLE git_commit_fts_rowid_map (
    fts_rowid INTEGER PRIMARY KEY,
    sha BLOB
);

CREATE INDEX idx_git_commit_fts_rowid_map_sha ON git_commit_fts_rowid_map(sha);

CREATE TRIGGER git_commits_fts_insert AFTER INSERT ON git_commits BEGIN
    DELETE FROM git_commits_fts WHERE rowid IN (
        SELECT fts_rowid FROM git_commit_fts_rowid_map WHERE sha = NEW.sha
    );
    DELETE FROM git_commit_fts_rowid_map WHERE sha = NEW.sha;
    INSERT INTO git_commits_fts(sha, project_path, message)
    VALUES (NEW.sha, NEW.project_path, NEW.message);
    INSERT INTO git_commit_fts_rowid_map(fts_rowid, sha)
    VALUES (last_insert_rowid(), NEW.sha);
END;

CREATE TRIGGER git_commits_fts_delete AFTER DELETE ON git_commits BEGIN
    DELETE FROM git_commits_fts WHERE rowid IN (
        SELECT fts_rowid FROM git_commit_fts_rowid_map WHERE sha = OLD.sha
    );
    DELETE FROM git_commit_fts_rowid_map WHERE sha = OLD.sha;
END;

CREATE TRIGGER git_commits_fts_update AFTER UPDATE OF message, project_path ON git_commits BEGIN
    DELETE FROM git_commits_fts WHERE rowid IN (
        SELECT fts_rowid FROM git_commit_fts_rowid_map WHERE sha = OLD.sha
    );
    DELETE FROM git_commit_fts_rowid_map WHERE sha = OLD.sha;
    INSERT INTO git_commits_fts(sha, project_path, message)
    VALUES (NEW.sha, NEW.project_path, NEW.message);
    INSERT INTO git_commit_fts_rowid_map(fts_rowid, sha)
    VALUES (last_insert_rowid(), NEW.sha);
END;

CREATE TRIGGER memories_authority_guard_insert
            BEFORE INSERT ON memories
            WHEN (EXISTS (SELECT 1 FROM authority_managed WHERE project_path = NEW.project_path)
               OR EXISTS (SELECT 1 FROM authority_repair_pending WHERE project_path = NEW.project_path))
              AND COALESCE((SELECT enabled FROM context_privilege_state WHERE id = 1), 0) = 0
            BEGIN SELECT RAISE(ABORT, 'context.db memory writes are managed by the Rust module'); END;

CREATE TRIGGER memories_authority_guard_update
            BEFORE UPDATE ON memories
            WHEN (EXISTS (SELECT 1 FROM authority_managed WHERE project_path = OLD.project_path)
               OR EXISTS (SELECT 1 FROM authority_managed WHERE project_path = NEW.project_path)
               OR EXISTS (SELECT 1 FROM authority_repair_pending WHERE project_path = OLD.project_path)
               OR EXISTS (SELECT 1 FROM authority_repair_pending WHERE project_path = NEW.project_path))
              AND COALESCE((SELECT enabled FROM context_privilege_state WHERE id = 1), 0) = 0
            BEGIN SELECT RAISE(ABORT, 'context.db memory writes are managed by the Rust module'); END;

CREATE TRIGGER memories_authority_guard_delete
            BEFORE DELETE ON memories
            WHEN (EXISTS (SELECT 1 FROM authority_managed WHERE project_path = OLD.project_path)
               OR EXISTS (SELECT 1 FROM authority_repair_pending WHERE project_path = OLD.project_path))
              AND COALESCE((SELECT enabled FROM context_privilege_state WHERE id = 1), 0) = 0
            BEGIN SELECT RAISE(ABORT, 'context.db memory writes are managed by the Rust module'); END;

CREATE TRIGGER notes_authority_guard_insert
            BEFORE INSERT ON notes
            WHEN (
        EXISTS (SELECT 1 FROM authority_managed WHERE project_path = NEW.project_path)
        OR EXISTS (SELECT 1 FROM authority_repair_pending WHERE project_path = NEW.project_path)
        OR EXISTS (
            SELECT 1 FROM session_projects sp
            JOIN authority_managed am ON am.project_path = sp.project_path
            WHERE sp.session_id = NEW.session_id
        )
        OR EXISTS (
            SELECT 1 FROM session_projects sp
            JOIN authority_repair_pending arp ON arp.project_path = sp.project_path
            WHERE sp.session_id = NEW.session_id
        )
    ) AND COALESCE((SELECT enabled FROM context_privilege_state WHERE id = 1), 0) = 0
            BEGIN SELECT RAISE(ABORT, 'context.db note writes are managed by the Rust module'); END;

CREATE TRIGGER notes_authority_guard_update
            BEFORE UPDATE ON notes
            WHEN ((
        EXISTS (SELECT 1 FROM authority_managed WHERE project_path = OLD.project_path)
        OR EXISTS (SELECT 1 FROM authority_repair_pending WHERE project_path = OLD.project_path)
        OR EXISTS (
            SELECT 1 FROM session_projects sp
            JOIN authority_managed am ON am.project_path = sp.project_path
            WHERE sp.session_id = OLD.session_id
        )
        OR EXISTS (
            SELECT 1 FROM session_projects sp
            JOIN authority_repair_pending arp ON arp.project_path = sp.project_path
            WHERE sp.session_id = OLD.session_id
        )
    ) OR (
        EXISTS (SELECT 1 FROM authority_managed WHERE project_path = NEW.project_path)
        OR EXISTS (SELECT 1 FROM authority_repair_pending WHERE project_path = NEW.project_path)
        OR EXISTS (
            SELECT 1 FROM session_projects sp
            JOIN authority_managed am ON am.project_path = sp.project_path
            WHERE sp.session_id = NEW.session_id
        )
        OR EXISTS (
            SELECT 1 FROM session_projects sp
            JOIN authority_repair_pending arp ON arp.project_path = sp.project_path
            WHERE sp.session_id = NEW.session_id
        )
    )) AND COALESCE((SELECT enabled FROM context_privilege_state WHERE id = 1), 0) = 0
            BEGIN SELECT RAISE(ABORT, 'context.db note writes are managed by the Rust module'); END;

CREATE TRIGGER notes_authority_guard_delete
            BEFORE DELETE ON notes
            WHEN (
        EXISTS (SELECT 1 FROM authority_managed WHERE project_path = OLD.project_path)
        OR EXISTS (SELECT 1 FROM authority_repair_pending WHERE project_path = OLD.project_path)
        OR EXISTS (
            SELECT 1 FROM session_projects sp
            JOIN authority_managed am ON am.project_path = sp.project_path
            WHERE sp.session_id = OLD.session_id
        )
        OR EXISTS (
            SELECT 1 FROM session_projects sp
            JOIN authority_repair_pending arp ON arp.project_path = sp.project_path
            WHERE sp.session_id = OLD.session_id
        )
    ) AND COALESCE((SELECT enabled FROM context_privilege_state WHERE id = 1), 0) = 0
            BEGIN SELECT RAISE(ABORT, 'context.db note writes are managed by the Rust module'); END;

